mapper.select:
SELECT PRODID, prodName, raisemode, VDATE, MDATE, raiseType, IVSTORIENTATION, ccy, operateMode, opentype, term, termtype, isTransfer, isBreakeven, isFhxgcp, excFinSector, isYllccp, isThisTrem, isEndTrem, sum(endamtsumOth) endamtsumOth, sum(payamtsum) payamtsum, sum(customeramt) customeramt, sum(bankamt) bankamt, sum(dirtyamtsum) dirtyamtsum, sum(cleanamtsum) cleanamtsum, sum(ordIdentified01) ordIdentified01, sum(ordIdentified02) ordIdentified02, sum(ordIdentified03) ordIdentified03, sum(ordIdentified04) ordIdentified04, sum(ordIdentified05) ordIdentified05, sum(ordIdentified06) ordIdentified06, sum(ordIdentified07) ordIdentified07, sum(ordIdentified08) ordIdentified08, sum(ordIdentified09) ordIdentified09 FROM ( SELECT P.POSUUID, P.PRODID, B.PROD_NAME prodName, P.RAISEMODE raisemode, B.VDATE, B.MDATE, B.raise_type raiseType, B.IVSTORIENTATION, P.ccy, B.OPERATE_MODE operateMode, CASE WHEN B.OPERATE_MODE = '03' THEN CASE WHEN B.cash_mana_cate = '01' THEN '01' WHEN B.termtype IN ('06','08','09') THEN '02' ELSE '99' END END opentype, P.TERMDAYS term, P.termtype, b.is_transfer isTransfer, decode(b.profit_type,'03','02','01') isBreakeven, b.is_fhxgcp isFhxgcp, B.exc_fin_sector excFinSector, B.IS_YLLCCP isYllccp, p.dirtyamtsum, p.cleanamtsum, CASE WHEN TO_CHAR(B.VDATE,'yyyyMM') = P.TERM then '01' else '02' end isThisTrem, DECODE(P.DURATIONFLAG,'02','02','01') isEndTrem, P.ENDAMTSUM_OTH endamtsumOth, P.PAYAMTSUM payamtsum, P.CUSTOMERAMT customeramt, P.BANKAMT bankamt, DECODE(ORD_IDENTIFIED,'01',P.ENDAMTSUM_OTH) ordIdentified01, DECODE(ORD_IDENTIFIED,'02',P.ENDAMTSUM_OTH) ordIdentified02, DECODE(ORD_IDENTIFIED,'03',P.ENDAMTSUM_OTH) ordIdentified03, DECODE(ORD_IDENTIFIED,'05',P.ENDAMTSUM_OTH) ordIdentified04, DECODE(ORD_IDENTIFIED,'06',P.ENDAMTSUM_OTH) ordIdentified05, DECODE(ORD_IDENTIFIED,'07',P.ENDAMTSUM_OTH) ordIdentified06, DECODE(ORD_IDENTIFIED,'08',P.ENDAMTSUM_OTH) ordIdentified07, DECODE(ORD_IDENTIFIED,'04',P.ENDAMTSUM_OTH) ordIdentified08, DECODE(ORD_IDENTIFIED,'09',P.ENDAMTSUM_OTH) ordIdentified09
FROM CHB_MONTH_PRD_POSITIONDETAIL P LEFT JOIN CHB_PRD_BASEINFO B ON P.PRODID= b.Prod_Id AND B.FPROD_ID IS NULL AND B.STATUS IN ('E','M') WHERE 1=1
and P.TERM = #{enddate,jdbcType=VARCHAR}
#{item}
) A
GROUP BY PRODID, prodName, raisemode, VDATE, MDATE, raiseType, IVSTORIENTATION, ccy, operateMode, opentype, term, termtype, isTransfer, isBreakeven, isFhxgcp, excFinSector, isYllccp, isThisTrem, isEndTrem
